select correlation_id, installation_id, flag_code, latest_phase, failure_code, retryable, historical_rate_limited, occurred_at from incidents where 1 = 1
and installation_id = #{installationId}
and flag_code = #{flagCode}
order by occurred_at desc limit #{limit}

select count(*)
from mentor_audit_logs
where installation_id = #{installationId}
  and event_type = 'chat_requested'
  and created_at >= #{windowStart}
